// === Explicit Template Specialization ===
template <typename T>
T get_default(T val) { return val; } // General

template <>
int get_default(int val) { return val + 10; } // Specialized for int

// === SFINAE for Conditional Overloading ===
// (Requires type_traits context)

// 1. General Template (Fallback)
template <typename T>
void execute(T) { /* Default behavior */ }

// 2. SFINAE Overload: Enabled only for Integral Types
template <typename T>
std::enable_if_t<std::is_integral_v<T>>* // Return type condition
execute(T val) {
    // Specific logic for T = int, short, etc.
    return nullptr;
}

// 3. SFINAE Overload: Enabled only for Floating Point Types
template <typename T>
std::enable_if_t<std::is_floating_point_v<T>>*
execute(T val) {
    // Specific logic for T = float, double
    return nullptr;
}
